def mutate_synonym(premises, rng, replace_prob=0.3):
    """Replace ~30 % of eligible content words with synonyms."""
    mutated, total_replaced = [], 0
    for premise in premises:
        words = premise.split()
        new_words = []
        for w in words:
            clean = re.sub(r'[^\w]', '', w).lower()

            if clean in QUANTIFIER_SYNONYMS and rng.random() < 0.5:
                cands = [c for c in QUANTIFIER_SYNONYMS[clean] if ' ' not in c]
                if cands:
                    rep = rng.choice(cands)
                    if w[0].isupper():
                        rep = rep.capitalize()
                    trail = re.search(r'(\W+)$', w)
                    if trail:
                        rep += trail.group(1)
                    new_words.append(rep)
                    total_replaced += 1
                    continue

            if (clean not in PROTECTED_WORDS
                    and len(clean) > 3
                    and rng.random() < replace_prob):
                syn = _get_synonym(clean)
                if syn:
                    if w[0].isupper():
                        syn = syn.capitalize()
                    trail = re.search(r'(\W+)$', w)
                    if trail:
                        syn += trail.group(1)
                    new_words.append(syn)
                    total_replaced += 1
                    continue

            new_words.append(w)
        mutated.append(' '.join(new_words))
    return mutated, total_replaced


